SELECT /* LGVPAY00018.retrieveUserDefineTableRowList */ udtm.table_seq_no , udtm.table_name , udtr.row_no , udtr.sort_order_no , udtr.sort_order_no AS ori_sort_order_no , udtr.lower_limit_critical_value , udtr.upper_limit_critical_value , TO_CHAR(TO_DATE(udtr.effective_start_yyyymmdd, 'YYYYMMDD'), 'DD/MM/YYYY') AS effective_start_yyyymmdd , TO_CHAR(TO_DATE(udtr.effective_end_yyyymmdd , 'YYYYMMDD'), 'DD/MM/YYYY') AS effective_end_yyyymmdd , TO_CHAR(TO_DATE(udtr.effective_start_yyyymmdd, 'YYYYMMDD'), 'DD/MM/YYYY') AS ori_effective_start_yyyymmdd FROM tb_pay_user_dfin_table_row_n udtr , tb_pay_user_dfin_table_m udtm WHERE udtm.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode} /* 해외법인코드 */ AND udtr.table_seq_no = udtm.table_seq_no AND udtm.table_seq_no = #{tableSeqNo, jdbcType=NUMERIC}
AND udtr.sort_order_no = #{sortOrderNo, jdbcType=NUMERIC}
ORDER BY udtm.table_name, udtr.sort_order_no
